Q: how can i optimise the following jquery logic A: <p>try this.     </p>

<pre><code>function toggleStudyFields(service_type) {
        $("#study_or_migrate").addClass("hidden");
        $("#study-fields").addClass("hidden");
        $("#fields-except-visa").addClass("hidden");
        $("#visa-fields").addClass("hidden");
        $("#coaching-fields").addClass("hidden");

        switch (service_type) {
            case "Study":
                $("#study-fields").removeClass("hidden");
                $("#fields-except-visa").removeClass("hidden");
                break;
            case "Visa":
                $("#visa-fields").removeClass("hidden");
                break;
            case "Coaching":
                $("#coaching-fields").removeClass("hidden");
                break;
            case "Invest":
                $("#fields-except-visa").removeClass("hidden");
                break;
            default:
                $("#study_or_migrate").removeClass("hidden");
                $("#fields-except-visa").removeClass("hidden");
                break;
        }
    }
</code></pre>

Q: How can I listen to an event inside a custom Readable stream in NodeJS? A: <p>I tried writing the 1.48GB csv file as json array into the file,it didn't give any errors  or warnings that you have mentioned.</p>

<pre><code>const http = require('http');
const fs = require('fs');
const csv = require('csv-parser');

const server = http.createServer();

const writeStr = fs.createWriteStream('data.json', { flags: 'a' });
writeStr.write('[\n');
let sep = "";

server.on('request', (req, res) =&gt; {
    console.log(req.method);

    fs.createReadStream('./Crimes_-_2001_to_present.csv').pipe(csv())
        .on('data', function (data) {
            writeStr.write(sep + JSON.stringify(data));
            if (!sep)
                sep = ",\n";
        })
        .on('end', function () {
            writeStr.write('\n]')
            console.log('DONE WRITING FILE');
            res.end();
        })
        .on('error', function (err) {
            consol.log(err);
        })
})
server.listen(8000);
</code></pre>

<p>FYI:the dataset is take from <a href="https://catalog.data.gov/dataset?res_format=CSV" rel="nofollow noreferrer">https://catalog.data.gov/dataset?res_format=CSV</a></p>
